  $('chart').innerHTML=`<svg class="microchip-timing" viewBox="0 0 520 182" role="img" aria-label="${t('Señales internas: gris pendiente; cada pista distingue nivel cero y uno. La parte futura permanece oculta.','Internal signals: grey means pending; each track distinguishes zero and one. Future values stay hidden.')}"><defs><clipPath id="microchip-chart-reveal"><rect id="microchip-chart-width" x="90" y="0" width="0" height="160"/></clipPath></defs>${model.series.map((series,i)=>{const base=35+i*49,known=series.values.findIndex(v=>v!==null),pts=series.values.flatMap((v,j)=>v===null?[]:[`${x(j)},${base+(v===0?12:-12)}`,...(j<12?[`${x(j+1)},${base+(v===0?12:-12)}`]:[])]).join(' ');return `<text x="3" y="${base+4}" fill="${colors[i]}" font-size="12">${['X','Sum','Cout'][i]}</text><text x="67" y="${base-8}" fill="#9eafbc" font-size="9">1</text><text x="67" y="${base+15}" fill="#9eafbc" font-size="9">0</text><line x1="90" x2="490" y1="${base}" y2="${base}" stroke="#314654"/><g clip-path="url(#microchip-chart-reveal)"><line class="logic-pending" x1="90" x2="${x(known<0?12:known)}" y1="${base}" y2="${base}" stroke="#8a9dad" stroke-width="3" stroke-dasharray="3 4"/><polyline class="logic-signal" fill="none" stroke="${series.values.find(v=>v!==null)===0?'#7ab9ff':'#84e7bc'}" stroke-width="3" points="${pts}"/></g>`;}).join('')}<line id="microchip-chart-cursor" x1="90" x2="90" y1="7" y2="159" stroke="#e6f2f5" stroke-width="1.5"/>${[0,4,8,10,12].map(i=>`<text x="${x(i)-4}" y="177" fill="#c7d9e6" font-size="11">${i}</text>`).join('')}</svg><p class="microchip-chart-note">${t('Salidas internas: X en 4, Sum en 8 y Cout en 10. Los indicadores reciben Sum y Cout en 12. Pasos pedagógicos, sin unidades de tiempo físico.','Internal outputs: X at 4, Sum at 8 and Cout at 10. Indicators receive Sum and Cout at 12. Teaching steps, without physical time units.')}</p>`;
